import {initial,scene,choose,pathName,art,migrate,relationshipEvents} from './engine.mjs';
import {journeyPanel} from './journey-ui.mjs';
import {zoneFor,xpNeeded} from './journey.mjs';
import {abilities,combatStats,weaponProfiles,elementDescriptions,tickBattle,fastForward,maxHp,maxEnergy} from './combat.mjs';
const $=id=>document.getElementById(id),key='hannui-first-breath-v1';
let state=null,saved=null,storageOk=true,saveWarning='',timer=null,paused=false,speed=1;
const escape=x=>String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
try{const raw=localStorage.getItem(key);if(raw){try{saved=migrate(JSON.parse(raw));}catch{saveWarning='기존 저장을 읽지 못했습니다. 새 여정을 시작할 수 있습니다.';}}}catch{storageOk=false;}
function persist(){try{localStorage.setItem(key,JSON.stringify(state));saved=structuredClone(state);storageOk=true;}catch{storageOk=false;}}
function stopTimer(){if(timer!==null)clearTimeout(timer);timer=null;}
function landing(){stopTimer();state=null;$('app').innerHTML=`<section class="hero flash"><div><p class="eyebrow">HAN NUI · AN ILLUSTRATED TEXT RPG</p><h1>당신의 이름으로,<br><em>첫 숨을 열다.</em></h1><p class="intro">무엇을 쥘 것인가. 어떤 힘을 따를 것인가.<br>당신의 선택이 길을 만들고,<br>쌓아 온 힘이 전장에서 이야기를 이어갑니다.</p><div class="hero-tags"><span>장면 삽화</span><span>선택과 성장</span><span>자동 전투</span></div><form id="start" class="name-form"><label for="name">이야기에 남길 이름</label><input id="name" name="name" maxlength="16" placeholder="제자의 이름을 입력하세요" autocomplete="off" required><p id="name-error" class="error" aria-live="polite">${escape(saveWarning)}</p><button class="primary wide">새로운 이야기 시작하기 ↗</button><div class="sub-action">${saved?`<button type="button" class="quiet" id="resume">${escape(saved.name)}의 이야기 이어가기 →</button>`:'<span class="muted">서장과 첫 번째 의뢰 · 탐험과 성장</span>'}</div></form></div><figure class="hero-art"><img src="assets/courtyard.png" alt="소나무와 운무가 감싼 산중 수련처 여울원, 새벽빛 아래 제자들이 수련한다." fetchpriority="high"><figcaption>여울원 · 모든 길이 시작되는 곳</figcaption></figure></section>`;
 $('start').onsubmit=e=>{e.preventDefault();const name=$('name').value.trim();if(!name||name.length>16){$('name-error').textContent='1~16자로 이름을 입력해 주세요.';return;}if(saved){$('new-name').value=name;$('restart').showModal();}else start(name);};if(saved)$('resume').onclick=()=>{state=migrate(saved);paused=state.scene==='battle'&&!state.battle.outcome;persist();render();};}
function start(name){stopTimer();state=initial(name);paused=false;persist();render();}
function bar(label,value,max,theme=''){return `<div class="stat ${theme}"><div class="stat-label"><span>${label}</span><span>${value} / ${max}</span></div><div class="bar"><i style="width:${Math.max(0,Math.min(100,value/max*100))}%"></i></div></div>`;}
function illustration(){if(state.journey){const z=['combat','battle'].includes(state.scene)?zoneFor(state.journey.active):state.scene==='reward'?zoneFor(state.journey.reward.zone):null;const file=z?.image||(['growth'].includes(state.scene)?'spring':'courtyard');return `<figure class="scene-art ${state.scene==='battle'?'battle-art':''}"><img src="assets/${file}.png" alt="산중의 수련처와 산 아래 길을 그린 삽화" width="1536" height="1024"><figcaption><span>${z?.name||'여울원 · 다시 길을 준비하는 자리'}</span><span>CHAPTER 01</span></figcaption></figure>`;}const spring=['spring','commit','element'].includes(state.scene),bridge=['mission','combat','battle','bridge'].includes(state.scene),file=bridge?'bridge':spring?'spring':'courtyard';const caption=bridge?'산 아래 계곡 · 끊어지는 다리':spring?'여울원의 샘 · 숨이 깨어나는 자리':'여울원 · 수련의 뜰';const alt=bridge?'안개 낀 계곡을 건너는 낡은 밧줄 다리, 건너편에 약탈자가 서 있다.':spring?'맑은 샘물 위로 옅은 옥빛 숨이 흐르고 잎 하나가 떠 있다.':'기와 지붕의 산중 수련처와 마당, 겹겹의 산 사이로 새벽빛이 든다.';return `<figure class="scene-art ${state.scene==='battle'?'battle-art':''}"><img src="assets/${file}.png" alt="${alt}" decoding="async" width="1536" height="1024"><figcaption><span>${caption}</span><span>${state.scene==='battle'?'ENCOUNTER 01':'HAN NUI'}</span></figcaption></figure>`;}
function sidebar(){const traits=[['길',pathName(state)],['결',state.element||'아직 드러나지 않음'],['무기 / 매개',state.weapon||'정하지 않음']];return `<aside class="sidebar"><div class="avatar"><span>${escape(state.element?.slice(0,1)||'숨')}</span></div><div class="profile"><h2>${escape(state.name)}</h2><span class="rank">${state.journey?'실전 등급 '+state.journey.level:state.scene==='ending'?'첫 깨달음을 얻은 제자':'여울원의 신입 제자'}</span></div><div class="rule"></div><div>${traits.map(([k,v])=>`<div class="trait"><span>${k}</span><span>${v}</span></div>`).join('')}</div><div class="rule"></div><div>${bar('체력',state.hp,maxHp(state),'health')}${bar(state.path==='outer'?'이끌 수 있는 숨':'사용 가능한 숨',state.energy,maxEnergy(state))}</div><div class="rule"></div><div><p class="eyebrow sidebar-label">쌓아 온 것</p>${[['제어',state.control],['숙련',state.skill],['통찰',state.insight]].map(([k,v])=>`<div class="trait"><span>${k}</span><span>${v}</span></div>`).join('')}</div><div class="known-arts"><p class="eyebrow">배운 기술</p>${abilities(state).length?abilities(state).map(a=>`<details><summary>${a.name}</summary><p>${a.description}<br>숨 ${a.cost} 소모</p></details>`).join(''):'<p class="muted">길과 무기를 정하면<br>첫 기술을 익힙니다.</p>'}</div>${state.journey?`<div class="journey-progress">${bar('실전 경험',state.journey.xp,xpNeeded(state.journey))}<div class="trait"><span>엽전</span><span>${state.journey.gold}</span></div><div class="trait"><span>도구 / 방호구</span><span>+${state.journey.gear} / +${state.journey.armor}</span></div></div>`:''}</aside>`;}
function choiceList(data){return `<div class="choice-caption">YOUR CHOICE · 당신의 선택</div><div class="choices">${data.choices.map((c,i)=>`<button class="choice" data-choice="${c.id}" ${c.disabled?'disabled':''}><span class="num">${String(i+1).padStart(2,'0')}</span><span><strong>${escape(c.title)}</strong><small>${escape(c.hint)}</small></span><span class="arrow" aria-hidden="true">↗</span></button>`).join('')}</div>`;}
function equipped(){return state.loadout??abilities(state).slice(0,2).map(a=>a.id);}
function preparation(){const stats=combatStats(state),p=weaponProfiles[state.weapon],selected=equipped();return `<section class="preparation"><div class="section-title"><span>전투 준비</span><small>배운 기술 ${abilities(state).length}개 · 장착 ${selected.length}/2</small></div><div class="combat-numbers"><span>위력 <b>${stats.attack}</b></span><span>방어 <b>${stats.defense}</b></span><span>속도 <b>${stats.speed}</b></span><span>명중 <b>${Math.round(stats.accuracy*100)}%</b></span></div><p class="muted">${state.weapon} · ${p.description}<br>${elementDescriptions[state.element]}</p><div class="loadout">${abilities(state).map(a=>`<button class="ability-card ${selected.includes(a.id)?'selected':''}" role="checkbox" aria-checked="${selected.includes(a.id)}" data-ability="${a.id}"><span class="ability-check" aria-hidden="true">${selected.includes(a.id)?'✓':'＋'}</span><span><small>${a.kind} · 숨 ${a.cost}</small><strong>${a.name}</strong><em>${a.description}</em></span></button>`).join('')}</div><p id="loadout-note" class="muted" role="status">기술을 눌러 장착하거나 해제하세요. 위에서부터 사용 가능한 공격 기술을 우선합니다. 방어 기술은 체력이 낮을 때 사용합니다. 기술을 모두 해제하면 기본 공격으로 싸웁니다.</p></section>`;}
function battleView(){const b=state.battle,done=!!b.outcome,outcome={victory:'승리',defeat:'전투 불능',retreat:'후퇴'}[b.outcome];return `<section class="battle-panel"><div class="battle-heading"><span class="battle-status ${done?'finished':''}">${done?outcome:paused?'일시 정지':'자동 전투 중'}</span><span>${b.round}번째 공방 · ${b.turn}회 행동</span></div><div class="fighters"><div class="fighter"><p class="eyebrow">YOUR APPRENTICE</p><h3>${escape(state.name)}</h3><p class="muted">${state.weapon} · ${state.element} · ${state.path==='inner'?'무인':'마법사'}</p>${bar('체력',state.hp,maxHp(state),'health')}${bar('숨',state.energy,maxEnergy(state))}<small>보호막 ${b.playerShield}${b.counter?' · 반격 태세':''}</small></div><span class="versus">對</span><div class="fighter enemy"><p class="eyebrow">OPPONENT</p><h3>${b.enemy.name}</h3><p class="muted">${b.enemy.weapon||'짧은 칼'} · ${b.enemy.heavyEvery||3}공방마다 강한 공격</p>${bar('체력',b.enemy.hp,b.enemy.maxHp,'enemy-health')}<div class="enemy-effects">${b.enemy.burn?'연소 ':''}${b.enemy.stun?'경직 ':''}${b.enemy.weaken?'공격 약화 ':''}${!b.enemy.burn&&!b.enemy.stun&&!b.enemy.weaken?'자세를 가다듬는다':''}</div></div></div><div class="battle-controls">${!done?`<button class="quiet" id="pause">${paused?'▶ 계속하기':'Ⅱ 일시 정지'}</button><label class="speed-label" for="speed">재생 속도 <select id="speed"><option value="1" ${speed===1?'selected':''}>1×</option><option value="2" ${speed===2?'selected':''}>2×</option><option value="4" ${speed===4?'selected':''}>4×</option></select></label><button class="quiet" id="skip">결과까지 진행 →</button>`:`<span class="muted">${b.outcome==='victory'?'준비한 힘으로 적을 물리쳤습니다.':'전투의 결과를 안고 이야기를 이어갑니다.'}</span>`}</div><div class="combat-log" role="log" aria-label="전투 기록" aria-live="off">${b.log.map(e=>`<div class="log-row ${e.actor}"><span>${e.actor==='system'?'—':e.round}</span><p><small>${{player:escape(state.name),enemy:escape(b.enemy.name),effect:'결의 효과',system:'전투'}[e.actor]}</small>${escape(e.text)}</p></div>`).join('')}</div><p class="sr-only" aria-live="polite">${done?`전투 종료. ${outcome}`:paused?'전투가 일시 정지되었습니다.':'자동으로 전투를 진행합니다.'}</p></section>`;}
function relationPanel(){const events=relationshipEvents(state);return `<details class="relations"><summary>인연의 기록 <span>이솔 · ${events.length}개의 기억</span></summary><p>수련처에서 만난 동료. 함께 겪은 사건이 두 사람 사이에 남습니다.</p>${events.length?`<ul>${events.map(e=>`<li>${escape(e)}</li>`).join('')}</ul>`:'<p class="muted">아직 함께한 사건이 기록되지 않았습니다.</p>'}</details>`;}
function battleHistory(){return state.battle?.outcome&&state.scene!=='battle'?`<details class="journal"><summary>최근 전투 기록 · ${{victory:'승리',defeat:'전투 불능',retreat:'후퇴'}[state.battle.outcome]}</summary><ol>${state.battle.log.map(e=>`<li>${escape(e.text)}</li>`).join('')}</ol></details>`:'';}
function render(focus=true){stopTimer();const data=scene(state),isBattle=state.scene==='battle';$('app').innerHTML=`<div class="game-layout">${sidebar()}<article class="story ${focus?'flash':''}"><div class="chapter-nav"><span>${state.journey?'첫 번째 의뢰 · 사라진 전령':'서장 · 첫 번째 숨 / '+['','이름과 길','수련의 날들','첫 번째 시련','당신의 발자국'][data.chapter]}</span><span class="dots" aria-label="4장 중 ${data.chapter}장">${[1,2,3,4].map(n=>`<i class="${n<=data.chapter?'active':''}"></i>`).join('')}</span></div>${illustration()}${state.last?`<div class="notice" role="status">${escape(state.last)}</div>`:''}<p class="eyebrow">${isBattle?'AUTOMATIC COMBAT':`${state.journey?'CHAPTER 01':`CHAPTER 0${data.chapter}`}`}</p><h1 tabindex="-1" id="scene-title">${data.title}</h1><div class="prose">${data.text.map(t=>`<p>${escape(t)}</p>`).join('')}</div>${data.quote?`<blockquote class="quote">${data.quote}</blockquote>`:''}${journeyPanel(state)}${state.scene==='combat'?preparation():''}${isBattle?battleView():''}${state.scene==='ending'?ending():data.choices.length?choiceList(state.scene==='map'?{...data,choices:data.choices.filter(c=>!c.id.startsWith('explore-'))}:data):''}<div class="story-bottom"><span class="saved">${storageOk?'이 브라우저에 자동 저장됨':'자동 저장 불가 · 현재 창에서 계속 플레이할 수 있습니다'}</span><button class="quiet" id="home">처음 화면으로</button></div>${relationPanel()}${battleHistory()}<details class="journal"><summary>여정의 기록 · ${state.journal.length}개의 선택</summary><ol>${state.journal.map(j=>`<li><span>${escape(j.scene)}</span> — ${escape(j.choice)}</li>`).join('')}</ol></details></article></div>`;
 document.querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>{state=choose(state,b.dataset.choice);paused=false;persist();render();});
 document.querySelectorAll('[data-ability]').forEach(b=>b.onclick=()=>{const id=b.dataset.ability,ids=[...equipped()];if(ids.includes(id))state.loadout=ids.filter(x=>x!==id);else if(ids.length<2)state.loadout=[...ids,id];else{$('loadout-note').textContent='기술은 두 개까지 장착할 수 있습니다. 먼저 하나를 해제하세요.';return;}persist();render(false);document.querySelector(`[data-ability="${id}"]`).focus({preventScroll:true});});
 $('home').onclick=landing;if($('download'))$('download').onclick=download;if($('replay'))$('replay').onclick=()=>{$('new-name').value=state.name;$('restart').showModal();};
 if(isBattle){if($('pause'))$('pause').onclick=()=>{paused=!paused;render(false);};if($('speed'))$('speed').onchange=e=>{speed=Number(e.target.value);render(false);};if($('skip'))$('skip').onclick=()=>{state=fastForward(state);persist();render(false);};const log=document.querySelector('.combat-log');if(log)log.scrollTop=log.scrollHeight;if(!state.battle.outcome&&!paused)timer=setTimeout(()=>{state=tickBattle(state);persist();render(false);},850/speed);}
 if(focus){$('scene-title').focus({preventScroll:true});window.scrollTo({top:0,behavior:'instant'});}}
function ending(){return `<div class="result-grid"><div><small>당신이 연 길</small><strong>${pathName(state)}</strong></div><div><small>첫 깨달음</small><strong>${art(state)}</strong></div><div><small>마을에 남긴 기억</small><strong>${{together:'함께 지킨 약속',child:'작은 생명의 은인',herbs:'약을 지킨 제자'}[state.ending]}</strong></div><div><small>이솔과의 인연</small><strong>${state.relations.includes('isol-injured')?'아직 남은 미안함':state.relations.includes('shared-rescue')?'서로 등을 맡긴 사이':'함께 길을 걸은 사이'}</strong></div></div><p class="muted">서장 완료 · 첫 깨달음이 실제로 사용할 수 있는 고유 기술이 되었습니다. 이 제자로 다음 의뢰에 나아갈 수 있습니다.</p><button class="primary journey-next" data-choice="next-chapter">첫 번째 의뢰로 나아가기 →</button><div class="sub-action"><button class="primary" id="download">여정 기록 내려받기</button><button class="quiet" id="replay">다른 제자로 시작하기 →</button></div>`;}
function download(){const text=`한뉘 · 첫 번째 숨\n${state.name}의 여정\n${pathName(state)} / ${state.element} / ${state.weapon}\n첫 깨달음: ${art(state)}\n\n`+state.journal.map((j,i)=>`${i+1}. ${j.scene}\n   ${j.choice}`).join('\n')+'\n\n인연의 기록\n'+relationshipEvents(state).join('\n')+(state.battle?'\n\n전투 기록\n'+state.battle.log.map(e=>`[${e.round}] ${e.text}`).join('\n'):'');const a=document.createElement('a'),url=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'}));a.href=url;a.download='한뉘-여정.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
document.body.insertAdjacentHTML('beforeend','<dialog id="restart"><h2>새로운 이야기를 시작할까요?</h2><p>현재 브라우저에 저장된 여정이 새 제자의 이야기로 바뀝니다.</p><input type="hidden" id="new-name"><div class="sub-action"><button class="primary" id="confirm-restart">새로 시작하기</button><button class="quiet" id="cancel-restart">돌아가기</button></div></dialog>');
$('confirm-restart').onclick=()=>{const name=$('new-name').value;$('restart').close();start(name);};$('cancel-restart').onclick=()=>$('restart').close();
let guideWasPlaying=false;$('help').onclick=()=>{guideWasPlaying=state?.scene==='battle'&&!paused&&!state.battle.outcome;if(guideWasPlaying){paused=true;render(false);}$('guide').showModal();};$('close-guide').onclick=()=>$('guide').close();$('guide').addEventListener('close',()=>{if(guideWasPlaying&&state?.scene==='battle'){paused=false;render(false);}guideWasPlaying=false;});$('brand').onclick=e=>{e.preventDefault();landing();};landing();
